<script setup lang="ts">
import { ref } from 'vue'; import { api } from '../api';
const emit=defineEmits<{close:[];applied:[]}>(); const payload=ref<unknown>(), preview=ref<any>(), error=ref(''), busy=ref(false);
async function choose(event:Event){preview.value=null;error.value='';const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;try{payload.value=JSON.parse(await file.text());busy.value=true;preview.value=await api.send('/api/admin/import/preview','POST',payload.value)}catch(e){error.value=e instanceof Error?e.message:'文件无效'}finally{busy.value=false}}
async function apply(){busy.value=true;try{preview.value=await api.send('/api/admin/import/apply','POST',payload.value);emit('applied')}catch(e){error.value=e instanceof Error?e.message:'导入失败'}finally{busy.value=false}}
</script>
<template><div class="modal" role="dialog" aria-modal="true" @click.self="emit('close')"><section class="panel dialog"><div class="page-head"><div><div class="eyebrow">JSON IMPORT</div><h2>导入来源</h2></div><button class="ghost" @click="emit('close')">✕</button></div><label class="drop">选择 LunaTV JSON 文件<input type="file" accept="application/json,.json" @change="choose"></label><p v-if="busy" role="status">正在处理…</p><p v-if="error" class="error">{{error}}</p><template v-if="preview"><div class="preview"><b>新增 {{preview.inserted}}</b><b>更新 {{preview.updated}}</b><b :class="{bad:preview.invalid}">无效 {{preview.invalid}}</b></div><ul v-if="preview.errors?.length" class="errors"><li v-for="item in preview.errors" :key="item.sourceKey+item.code"><code>{{item.sourceKey||'(空键)'}}</code>：{{item.message}}</li></ul><p v-else class="good">校验通过，可以应用。</p><footer><button class="ghost" @click="emit('close')">取消</button><button class="primary" :disabled="busy" @click="apply">应用有效条目</button></footer></template></section></div></template>
